-- REVIEW CANDIDATE ONLY. Generated by Supabase CLI; not applied remotely.
-- Additive; no owner provisioned, no real code issued, no payment/redeem activation.
begin;
create table bud_platform.platform_owners (
 host_id uuid primary key references auth.users(id) on delete restrict,
 discord_id text not null unique check(discord_id ~ '^[1-9][0-9]{5,19}$')
);
create table bud_platform.owner_audit (
 id uuid primary key default gen_random_uuid(), actor uuid not null references auth.users(id),
 operation_id uuid not null, kind text not null, subject text not null,
 reason text not null check(length(reason) between 3 and 300), outcome jsonb not null,
 created_at timestamptz not null default clock_timestamp(), unique(actor,operation_id)
);
create table bud_platform.redeem_codes (
 id uuid primary key default gen_random_uuid(), digest text not null unique check(digest ~ '^[a-f0-9]{64}$'),
 qty integer not null check(qty between 1 and 100), max_uses integer not null check(max_uses between 1 and 10000),
 uses integer not null default 0 check(uses>=0 and uses<=max_uses), expires_at timestamptz not null,
 suspended boolean not null default false, created_by uuid not null references auth.users(id),
 operation_id uuid not null, created_at timestamptz not null default clock_timestamp(), unique(created_by,operation_id)
);
create table bud_platform.bonus_ledger (
 id uuid primary key default gen_random_uuid(), host_id uuid not null references auth.users(id),
 source text not null check(source in ('redeem','admin_grant')), code_id uuid references bud_platform.redeem_codes(id),
 actor uuid not null references auth.users(id), operation_id uuid not null,
 qty integer not null check(qty between 1 and 100), reason text not null,
 created_at timestamptz not null default clock_timestamp(), unique(actor,operation_id), unique(code_id,host_id),
 check((source='redeem')=(code_id is not null))
);
create index bud_bonus_ledger_host on bud_platform.bonus_ledger(host_id,created_at desc);
create table bud_platform.user_restrictions (
 host_id uuid primary key references auth.users(id), suspended boolean not null,
 reason text not null, actor uuid not null references auth.users(id), updated_at timestamptz not null default clock_timestamp()
);
create table bud_platform.owner_settings (
 name text primary key check(name in ('operations_note')), value text not null check(length(value)<=500)
);
create table bud_platform.owner_alerts (
 fingerprint text primary key check(length(fingerprint) between 1 and 160), severity text not null check(severity in ('P0','P1','P2')),
 kind text not null, subject text not null, active boolean not null,
 first_seen timestamptz not null default clock_timestamp(), last_seen timestamptz not null default clock_timestamp(),
 acknowledged_at timestamptz, acknowledged_by uuid references auth.users(id), resolved_at timestamptz,
 notified_at timestamptz
);
create index bud_owner_audit_created on bud_platform.owner_audit(created_at desc);
create table bud_platform.owner_access_events (
 id uuid primary key default gen_random_uuid(),actor uuid references auth.users(id),
 kind text not null check(kind in ('authentication_failed','owner_denied','issuance_denied','operation_failed')),
 created_at timestamptz not null default clock_timestamp()
);
create index bud_owner_access_created on bud_platform.owner_access_events(created_at desc);
create index bud_redeem_codes_created on bud_platform.redeem_codes(created_at desc);
create table bud_platform.owner_notification_jobs (
 id uuid primary key default gen_random_uuid(), fingerprint text not null references bud_platform.owner_alerts(fingerprint),
 cycle timestamptz not null, generation integer not null, recipient_digest text not null check(recipient_digest ~ '^[a-f0-9]{64}$'),
 severity text not null, kind text not null, subject text not null,
 status text not null default 'pending' check(status in ('pending','sending','accepted','review')),
 first_attempt_at timestamptz, lease_token uuid, lease_until timestamptz, available_at timestamptz not null default clock_timestamp(),
 attempts integer not null default 0, provider_id uuid, accepted_at timestamptz,
 unique(fingerprint,cycle,generation)
);
create index bud_owner_notification_due on bud_platform.owner_notification_jobs(available_at) where status in ('pending','sending');
do $$ declare t text; begin
 foreach t in array array['platform_owners','owner_audit','redeem_codes','bonus_ledger','user_restrictions','owner_settings','owner_alerts','owner_notification_jobs','owner_access_events'] loop
  execute format('alter table bud_platform.%I enable row level security',t);
  execute format('revoke all on bud_platform.%I from public,anon,authenticated,service_role',t);
  execute format('grant select on bud_platform.%I to service_role',t);
 end loop;
end $$;
grant insert on bud_platform.owner_audit,bud_platform.bonus_ledger to service_role;
grant insert on bud_platform.owner_access_events to service_role;
grant insert,update on bud_platform.redeem_codes,bud_platform.user_restrictions,bud_platform.owner_settings,bud_platform.owner_alerts to service_role;
grant insert,update on bud_platform.owner_notification_jobs to service_role;
-- Owners are provisioned by a separate reviewed operator statement, never by signup/client claims.
create function public.bud_owner_check(p_actor uuid,p_discord text) returns boolean
language sql stable security invoker set search_path='' as $$
 select exists(select 1 from bud_platform.platform_owners where host_id=p_actor and discord_id=p_discord);
$$;
create function bud_platform.require_owner(p_actor uuid,p_discord text) returns void
language plpgsql security invoker set search_path='' as $$
begin
 if not public.bud_owner_check(p_actor,p_discord) then raise exception 'BUD_OWNER_REQUIRED'; end if;
end;
$$;
create function public.bud_owner_access_event(p_actor uuid,p_kind text) returns jsonb
language plpgsql security invoker set search_path='' as $$
begin
 insert into bud_platform.owner_access_events(actor,kind) values(p_actor,p_kind);
 return jsonb_build_object('recorded',true);
end;
$$;
-- Narrow privileged helper: service_role cannot read Auth tables directly. No emails/tokens/raw metadata returned.
-- Both owner identifiers must match the private allowlist; pagination/substring length are bounded.
create function bud_platform.owner_directory(p_actor uuid,p_discord text,p_search text,p_offset integer) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare v_rows jsonb;
begin
 perform bud_platform.require_owner(p_actor,p_discord);
 if p_search is null or length(p_search)>80 or p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'BUD_INVALID_REQUEST'; end if;
 select coalesce(jsonb_agg(x),'[]'::jsonb) into v_rows from (
  select u.id,u.created_at,coalesce(i.identity_data->>'full_name','حساب Discord') as name,
   coalesce(i.identity_data->>'provider_id',i.identity_data->>'sub') as discord_id
  from auth.users u join auth.identities i on i.user_id=u.id and i.provider='discord'
  where p_search='' or position(lower(p_search) in lower(u.id::text||' '||coalesce(i.identity_data->>'full_name','')||' '||coalesce(i.identity_data->>'provider_id',i.identity_data->>'sub','')))>0
  order by u.created_at desc,u.id limit 50 offset p_offset
 ) x;
 return v_rows;
end;
$$;
create function bud_platform.owner_user_count(p_actor uuid,p_discord text) returns bigint
language plpgsql stable security definer set search_path='' as $$
begin
 perform bud_platform.require_owner(p_actor,p_discord);
 return (select count(distinct user_id) from auth.identities where provider='discord');
end;
$$;
create function public.bud_owner_view(p_actor uuid,p_discord text,p_section text,p_search text default '',p_offset integer default 0) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare v_rows jsonb; v_user uuid;
begin
 perform bud_platform.require_owner(p_actor,p_discord);
 if p_search is null or length(p_search)>80 or p_offset is null or p_offset<0 or p_offset>100000 then raise exception 'BUD_INVALID_REQUEST'; end if;
 case p_section
 when 'overview' then
  return jsonb_build_object('users',bud_platform.owner_user_count(p_actor,p_discord),'wallets',(select count(*) from bud_platform.live_wallets),'slots',(select coalesce(sum(credits),0) from bud_platform.live_wallets),
   'orders',(select count(*) from bud_platform.live_orders),'pendingOrders',(select count(*) from bud_platform.live_orders where fulfilled_at is null),
   'events',(select count(*) from bud_platform.live_events),'codes',(select count(*) from bud_platform.redeem_codes),
   'redemptions',(select count(*) from bud_platform.bonus_ledger where source='redeem'),'health',public.bud_live_operations_health(),
   'alerts',(select coalesce(jsonb_agg(a order by severity,last_seen desc),'[]'::jsonb) from bud_platform.owner_alerts a where active));
 when 'users' then
  return jsonb_build_object('rows',bud_platform.owner_directory(p_actor,p_discord,p_search,p_offset));
 when 'user' then
  if p_search !~ '^[a-fA-F0-9-]{36}$' then raise exception 'BUD_INVALID_REQUEST'; end if;
  v_user:=p_search::uuid;
  return jsonb_build_object('user',(select x from jsonb_array_elements(bud_platform.owner_directory(p_actor,p_discord,p_search,0)) x where x->>'id'=p_search),
   'credits',coalesce((select credits from bud_platform.live_wallets where host_id=v_user),0),
   'restriction',(select to_jsonb(r)-'actor' from bud_platform.user_restrictions r where host_id=v_user),
   'orders',(select coalesce(jsonb_agg(x),'[]'::jsonb) from(select id,amount_minor,currency,created_at,fulfilled_at from bud_platform.live_orders where host_id=v_user order by created_at desc limit 50)x),
   'grants',(select coalesce(jsonb_agg(x),'[]'::jsonb) from(select id,source,qty,created_at from bud_platform.bonus_ledger where host_id=v_user order by created_at desc limit 50)x),
   'events',(select coalesce(jsonb_agg(x),'[]'::jsonb) from(select id,title,phase,started_at,updated_at from bud_platform.live_events where host_id=v_user order by started_at desc limit 50)x));
 when 'keys' then
  select coalesce(jsonb_agg(x),'[]'::jsonb) into v_rows from(select id,qty,max_uses,uses,expires_at,suspended,created_at from bud_platform.redeem_codes
   where p_search='' or position(p_search in id::text)>0 order by created_at desc,id limit 50 offset p_offset)x;
 when 'payments' then
  select coalesce(jsonb_agg(x),'[]'::jsonb) into v_rows from(select o.id,o.host_id,o.amount_minor,o.currency,o.created_at,o.fulfilled_at,
    case when r.state in ('review','refunded','disputed') then r.state when o.fulfilled_at is null then 'pending' else 'confirmed' end as state
   from bud_platform.live_orders o left join bud_platform.live_reconciliation r on r.order_id=o.id
   where p_search='' or position(p_search in o.id::text)>0 order by o.created_at desc,o.id limit 50 offset p_offset)x;
 when 'events' then
  select coalesce(jsonb_agg(x),'[]'::jsonb) into v_rows from(select id,host_id,title,phase,started_at,updated_at
   from bud_platform.live_events where p_search='' or position(lower(p_search) in lower(id::text||' '||title))>0 order by started_at desc,id limit 50 offset p_offset)x;
 when 'audit' then
  select coalesce(jsonb_agg(x),'[]'::jsonb) into v_rows from(select * from bud_platform.owner_audit
   where p_search='' or position(lower(p_search) in lower(subject||' '||kind))>0 order by created_at desc,id limit 50 offset p_offset)x;
 when 'health' then
  return jsonb_build_object('database','ok','payments',public.bud_live_operations_health(),'discord','unknown','whop','unknown','vercel','unknown');
 when 'settings' then
  select coalesce(jsonb_agg(x),'[]'::jsonb) into v_rows from(select name,value from bud_platform.owner_settings)x;
 when 'search' then
  if length(trim(p_search))<2 then raise exception 'BUD_INVALID_REQUEST'; end if;
  return jsonb_build_object('users',public.bud_owner_view(p_actor,p_discord,'users',p_search,p_offset),
   'payments',public.bud_owner_view(p_actor,p_discord,'payments',p_search,p_offset),
   'events',public.bud_owner_view(p_actor,p_discord,'events',p_search,p_offset),
   'keys',public.bud_owner_view(p_actor,p_discord,'keys',p_search,p_offset));
 else raise exception 'BUD_INVALID_REQUEST';
 end case;
 return jsonb_build_object('rows',v_rows,'offset',p_offset,'pageSize',50,'mayHaveMore',jsonb_array_length(v_rows)=50)
  ||case when p_section='keys' then jsonb_build_object('history',(select coalesce(jsonb_agg(x),'[]'::jsonb)
    from(select id,host_id,source,code_id,qty,created_at from bud_platform.bonus_ledger order by created_at desc,id limit 50 offset p_offset)x)) else '{}'::jsonb end
  ||case when p_section='audit' then jsonb_build_object('accessEvents',(select coalesce(jsonb_agg(x),'[]'::jsonb)
    from(select id,actor,kind,created_at from bud_platform.owner_access_events order by created_at desc,id limit 50 offset p_offset)x)) else '{}'::jsonb end;
end;
$$;
create function public.bud_bonus_redeem(p_host uuid,p_digest text,p_operation uuid) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare v_code bud_platform.redeem_codes; v_receipt bud_platform.bonus_ledger; v_credit integer;
begin
 if p_host is null or p_operation is null or p_digest is null or p_digest !~ '^[a-f0-9]{64}$' then raise exception 'BUD_INVALID_CODE'; end if;
 -- Host lock orders competing request IDs, grants and starts consistently; code lock caps cross-account usage.
 perform pg_advisory_xact_lock(hashtextextended(p_host::text,26));
 select * into v_receipt from bud_platform.bonus_ledger where actor=p_host and operation_id=p_operation;
 if found then
  if v_receipt.source<>'redeem' or not exists(select 1 from bud_platform.redeem_codes where id=v_receipt.code_id and digest=p_digest) then raise exception 'BUD_KEY_REUSED'; end if;
  return jsonb_build_object('receipt',v_receipt.id,'qty',v_receipt.qty,'replayed',true,'credits',coalesce((select credits from bud_platform.live_wallets where host_id=p_host),0));
 end if;
 if exists(select 1 from bud_platform.user_restrictions where host_id=p_host and suspended) then raise exception 'BUD_ACCOUNT_RESTRICTED'; end if;
 select * into v_code from bud_platform.redeem_codes where digest=p_digest for update;
 if not found or v_code.suspended or v_code.expires_at<=clock_timestamp() or v_code.uses>=v_code.max_uses
  or exists(select 1 from bud_platform.bonus_ledger where code_id=v_code.id and host_id=p_host) then raise exception 'BUD_INVALID_CODE'; end if;
 update bud_platform.redeem_codes set uses=uses+1 where id=v_code.id;
 insert into bud_platform.bonus_ledger(host_id,source,code_id,actor,operation_id,qty,reason)
  values(p_host,'redeem',v_code.id,p_host,p_operation,v_code.qty,'استرداد مفتاح') returning * into v_receipt;
 insert into bud_platform.live_wallets(host_id,credits) values(p_host,v_code.qty)
  on conflict(host_id) do update set credits=bud_platform.live_wallets.credits+excluded.credits returning credits into v_credit;
 return jsonb_build_object('receipt',v_receipt.id,'qty',v_code.qty,'replayed',false,'credits',v_credit);
end;
$$;
create function public.bud_owner_command(p_actor uuid,p_discord text,p_operation uuid,p_kind text,p_body jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare v_old bud_platform.owner_audit; v_result jsonb; v_id uuid; v_host uuid; v_reason text; v_code bud_platform.redeem_codes;
begin
 perform bud_platform.require_owner(p_actor,p_discord);
 if p_operation is null or p_body is null then raise exception 'BUD_INVALID_REQUEST'; end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text||p_operation::text,27));
 select * into v_old from bud_platform.owner_audit where actor=p_actor and operation_id=p_operation;
 if found then
  if v_old.kind<>p_kind or v_old.outcome->'request' is distinct from (p_body-'digest') then raise exception 'BUD_KEY_REUSED'; end if;
  return (v_old.outcome-'request')||jsonb_build_object('replayed',true);
 end if;
 v_reason:=p_body->>'reason';
 if v_reason is null or length(trim(v_reason)) not between 3 and 300 then raise exception 'BUD_INVALID_REQUEST'; end if;
 case p_kind
 when 'createCode' then
  if (p_body->>'qty')::integer not between 1 and 100 or (p_body->>'maxUses')::integer not between 1 and 10000
   or (p_body->>'expiresAt')::timestamptz<=clock_timestamp() then raise exception 'BUD_INVALID_REQUEST'; end if;
  insert into bud_platform.redeem_codes(digest,qty,max_uses,expires_at,created_by,operation_id)
   values(p_body->>'digest',(p_body->>'qty')::integer,(p_body->>'maxUses')::integer,(p_body->>'expiresAt')::timestamptz,p_actor,p_operation) returning id into v_id;
  v_result:=jsonb_build_object('id',v_id,'created',true);
 when 'suspendCode' then
  v_id:=(p_body->>'id')::uuid;
  select * into v_code from bud_platform.redeem_codes where id=v_id for update;
  if not found then raise exception 'BUD_RESOURCE_NOT_FOUND'; end if;
  update bud_platform.redeem_codes set suspended=true where id=v_id;
  v_result:=jsonb_build_object('id',v_id,'suspended',true);
 when 'grant' then
  v_host:=(p_body->>'hostId')::uuid;
  if (p_body->>'qty')::integer not between 1 and 100 then raise exception 'BUD_INVALID_REQUEST'; end if;
  perform pg_advisory_xact_lock(hashtextextended(v_host::text,26));
  insert into bud_platform.live_wallets(host_id,credits) values(v_host,0) on conflict do nothing;
  perform 1 from bud_platform.live_wallets where host_id=v_host for update;
  if exists(select 1 from bud_platform.user_restrictions where host_id=v_host and suspended) then raise exception 'BUD_ACCOUNT_RESTRICTED'; end if;
  if jsonb_array_length(bud_platform.owner_directory(p_actor,p_discord,v_host::text,0))<>1 then raise exception 'BUD_RESOURCE_NOT_FOUND'; end if;
  insert into bud_platform.bonus_ledger(host_id,source,actor,operation_id,qty,reason)
   values(v_host,'admin_grant',p_actor,p_operation,(p_body->>'qty')::integer,v_reason) returning id into v_id;
  insert into bud_platform.live_wallets(host_id,credits) values(v_host,(p_body->>'qty')::integer)
   on conflict(host_id) do update set credits=bud_platform.live_wallets.credits+excluded.credits;
  v_result:=jsonb_build_object('id',v_id,'hostId',v_host,'qty',(p_body->>'qty')::integer);
 when 'restrict' then
  v_host:=(p_body->>'hostId')::uuid;
  perform pg_advisory_xact_lock(hashtextextended(v_host::text,26));
  if v_host=p_actor or exists(select 1 from bud_platform.platform_owners where host_id=v_host) then raise exception 'BUD_INVALID_REQUEST'; end if;
  insert into bud_platform.live_wallets(host_id,credits) values(v_host,0) on conflict do nothing;
  perform 1 from bud_platform.live_wallets where host_id=v_host for update;
  insert into bud_platform.user_restrictions(host_id,suspended,reason,actor)
   values(v_host,(p_body->>'suspended')::boolean,v_reason,p_actor)
   on conflict(host_id) do update set suspended=excluded.suspended,reason=excluded.reason,actor=excluded.actor,updated_at=clock_timestamp();
  v_result:=jsonb_build_object('hostId',v_host,'suspended',(p_body->>'suspended')::boolean);
 when 'setting' then
  if p_body->>'name'<>'operations_note' or length(p_body->>'value')>500 then raise exception 'BUD_INVALID_REQUEST'; end if;
  insert into bud_platform.owner_settings(name,value) values(p_body->>'name',p_body->>'value') on conflict(name) do update set value=excluded.value;
  v_result:=jsonb_build_object('saved',true);
 when 'ack' then
  update bud_platform.owner_alerts set acknowledged_at=clock_timestamp(),acknowledged_by=p_actor where fingerprint=p_body->>'fingerprint' and active;
  if not found then raise exception 'BUD_RESOURCE_NOT_FOUND'; end if;
  v_result:=jsonb_build_object('acknowledged',true);
 else raise exception 'BUD_INVALID_REQUEST';
 end case;
 insert into bud_platform.owner_audit(actor,operation_id,kind,subject,reason,outcome)
  values(p_actor,p_operation,p_kind,coalesce(v_host::text,v_id::text,p_body->>'name',p_body->>'fingerprint',''),v_reason,
   v_result||jsonb_build_object('request',p_body-'digest'));
 return v_result||jsonb_build_object('replayed',false);
end;
$$;
create function public.bud_owner_recover_payment(p_actor uuid,p_discord text,p_operation uuid,p_order uuid,p_payment text,p_expected jsonb,p_reason text) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare v_old bud_platform.owner_audit; v_order bud_platform.live_orders; v_result jsonb; v_request jsonb;
begin
 perform bud_platform.require_owner(p_actor,p_discord);
 if p_operation is null or p_order is null or p_payment is null or p_payment !~ '^pay_[A-Za-z0-9]{5,80}$' or p_reason is null or length(trim(p_reason)) not between 3 and 300 then raise exception 'BUD_INVALID_REQUEST'; end if;
 v_request:=jsonb_build_object('orderId',p_order,'paymentId',p_payment,'reason',p_reason);
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text||p_operation::text,27));
 select * into v_old from bud_platform.owner_audit where actor=p_actor and operation_id=p_operation;
 if found then
  if v_old.kind<>'recoverPayment' or v_old.outcome->'request' is distinct from v_request then raise exception 'BUD_KEY_REUSED'; end if;
  return (v_old.outcome-'request')||jsonb_build_object('replayed',true);
 end if;
 select * into v_order from bud_platform.live_orders where id=p_order for update;
 if not found or public.bud_live_order(p_order) is distinct from p_expected then raise exception 'BUD_INVALID_REQUEST'; end if;
 -- Only the server's authoritative Whop GET permits calling this service-only transaction.
 -- Recovery delivery IDs are explicitly operator receipts, never fabricated provider webhook envelopes.
 v_result:=public.bud_live_credit_purchase(v_order.id,v_order.company_id,v_order.product_id,v_order.plan_id,v_order.currency,
  v_order.amount_minor,v_order.checkout_id,p_payment,'msg_recovery'||replace(p_operation::text,'-',''));
 insert into bud_platform.owner_audit(actor,operation_id,kind,subject,reason,outcome)
  values(p_actor,p_operation,'recoverPayment',p_order::text,p_reason,v_result||jsonb_build_object('request',v_request));
 return v_result;
end;
$$;
create function public.bud_owner_sync_alerts(p_actor uuid,p_discord text,p_stale_seconds integer,p_expiry_seconds integer default 0,p_failure_limit integer default 0) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare v_now timestamptz:=clock_timestamp(); v_item record;
begin
 perform bud_platform.require_owner(p_actor,p_discord);
 if p_stale_seconds is null or p_stale_seconds<60 or p_stale_seconds>86400 or p_expiry_seconds is null or p_expiry_seconds<0 or p_expiry_seconds>2592000
  or p_failure_limit is null or p_failure_limit<0 or p_failure_limit>10000 then raise exception 'BUD_INVALID_REQUEST'; end if;
 -- Missing/stale telemetry remains UNKNOWN in health; warnings describe missing evidence, not proven outages.
 for v_item in
  select 'worker:'||task as fingerprint,'P1'::text as severity,'worker_telemetry_stale'::text as kind,task as subject,
   (succeeded_at is null or succeeded_at<v_now-make_interval(secs=>p_stale_seconds)) as active from bud_platform.live_worker_health
  union all
  select 'payment:'||message_id,'P0','payment_delivery_delayed',message_id,
   status<>'done' and created_at<v_now-make_interval(secs=>p_stale_seconds) from bud_platform.live_payment_jobs
  union all
  select 'reconciliation:'||order_id,'P1','payment_review',order_id::text,state in ('review','refunded','disputed') from bud_platform.live_reconciliation
  union all
  select 'code:'||id,'P2','code_expiring',id::text,p_expiry_seconds>0 and not suspended and uses<max_uses and expires_at>v_now and expires_at<v_now+make_interval(secs=>p_expiry_seconds) from bud_platform.redeem_codes
  union all
  select 'security:issuance','P0','issuance_denied','owner_access',exists(select 1 from bud_platform.owner_access_events where kind='issuance_denied' and created_at>v_now-make_interval(secs=>p_stale_seconds))
  union all
  select 'security:authentication','P0','authentication_failures','owner_access',p_failure_limit>0 and
   (select count(*) from bud_platform.owner_access_events where kind='authentication_failed' and created_at>v_now-make_interval(secs=>p_stale_seconds))>=p_failure_limit
 loop
  insert into bud_platform.owner_alerts(fingerprint,severity,kind,subject,active,first_seen,last_seen,resolved_at)
   values(v_item.fingerprint,v_item.severity,v_item.kind,v_item.subject,v_item.active,v_now,v_now,case when v_item.active then null else v_now end)
  on conflict(fingerprint) do update set active=excluded.active,last_seen=excluded.last_seen,
   first_seen=case when excluded.active and not bud_platform.owner_alerts.active then excluded.first_seen else bud_platform.owner_alerts.first_seen end,
   acknowledged_at=case when excluded.active and not bud_platform.owner_alerts.active then null else bud_platform.owner_alerts.acknowledged_at end,
   acknowledged_by=case when excluded.active and not bud_platform.owner_alerts.active then null else bud_platform.owner_alerts.acknowledged_by end,
   notified_at=case when excluded.active and not bud_platform.owner_alerts.active then null else bud_platform.owner_alerts.notified_at end,
   resolved_at=case when excluded.active then null else coalesce(bud_platform.owner_alerts.resolved_at,excluded.resolved_at) end;
 end loop;
 return jsonb_build_object('refreshed',true,'active',(select count(*) from bud_platform.owner_alerts where active));
end;
$$;
create function bud_platform.guard_owner_restriction() returns trigger
language plpgsql security invoker set search_path='' as $$
begin
 perform 1 from bud_platform.live_wallets where host_id=new.host_id for update;
 if exists(select 1 from bud_platform.user_restrictions where host_id=new.host_id and suspended) then raise exception 'BUD_ACCOUNT_RESTRICTED'; end if;
 return new;
end;
$$;
create trigger bud_owner_order_restriction before insert on bud_platform.live_orders for each row execute function bud_platform.guard_owner_restriction();
create trigger bud_owner_event_restriction before insert on bud_platform.live_events for each row execute function bud_platform.guard_owner_restriction();
create function public.bud_owner_claim_notification(p_actor uuid,p_discord text,p_recipient_digest text,p_escalation_seconds integer) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare v_alert bud_platform.owner_alerts; v_job bud_platform.owner_notification_jobs; v_generation integer;
begin
 perform bud_platform.require_owner(p_actor,p_discord);
 if p_recipient_digest is null or p_recipient_digest !~ '^[a-f0-9]{64}$' or p_escalation_seconds is null or p_escalation_seconds<300 or p_escalation_seconds>86400 then raise exception 'BUD_INVALID_REQUEST'; end if;
 -- First serialize cycles on the alert; concurrent cron invocations cannot create duplicate notifications.
 for v_alert in select * from bud_platform.owner_alerts where active and severity in ('P0','P1') order by severity,first_seen for update skip locked loop
  select coalesce(max(generation),0) into v_generation from bud_platform.owner_notification_jobs where fingerprint=v_alert.fingerprint and cycle=v_alert.first_seen;
  if v_generation=0 or (v_alert.severity='P0' and v_alert.notified_at is not null and v_alert.notified_at<clock_timestamp()-make_interval(secs=>p_escalation_seconds)
    and not exists(select 1 from bud_platform.owner_notification_jobs where fingerprint=v_alert.fingerprint and cycle=v_alert.first_seen and status<>'accepted')) then
   insert into bud_platform.owner_notification_jobs(fingerprint,cycle,generation,recipient_digest,severity,kind,subject)
    values(v_alert.fingerprint,v_alert.first_seen,v_generation+1,p_recipient_digest,v_alert.severity,v_alert.kind,v_alert.subject);
  end if;
 end loop;
 -- Never blindly resend beyond the provider's 24-hour idempotency window.
 update bud_platform.owner_notification_jobs set status='review',lease_token=null,lease_until=null
  where status in ('pending','sending') and (first_attempt_at<clock_timestamp()-interval '23 hours' or recipient_digest<>p_recipient_digest);
 select j.* into v_job from bud_platform.owner_notification_jobs j join bud_platform.owner_alerts a on a.fingerprint=j.fingerprint and a.first_seen=j.cycle
  where a.active and j.status in ('pending','sending') and j.available_at<=clock_timestamp()
   and (j.lease_until is null or j.lease_until<=clock_timestamp()) order by j.available_at limit 1 for update of j skip locked;
 if not found then return null; end if;
 update bud_platform.owner_notification_jobs set status='sending',first_attempt_at=coalesce(first_attempt_at,clock_timestamp()),attempts=attempts+1,
  lease_token=gen_random_uuid(),lease_until=clock_timestamp()+interval '2 minutes' where id=v_job.id returning * into v_job;
 return jsonb_build_object('id',v_job.id,'lease',v_job.lease_token,'severity',v_job.severity,'kind',v_job.kind,'subject',v_job.subject,'cycle',v_job.cycle,'generation',v_job.generation);
end;
$$;
create function public.bud_owner_finish_notification(p_actor uuid,p_discord text,p_job uuid,p_lease uuid,p_provider uuid,p_retry boolean) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare v_job bud_platform.owner_notification_jobs;
begin
 perform bud_platform.require_owner(p_actor,p_discord);
 select * into v_job from bud_platform.owner_notification_jobs where id=p_job for update;
 if not found or v_job.status<>'sending' or p_lease is null or v_job.lease_token is distinct from p_lease or v_job.lease_until<=clock_timestamp() then raise exception 'BUD_NOTIFICATION_LEASE_LOST'; end if;
 update bud_platform.owner_notification_jobs set status=case when p_provider is not null then 'accepted' when p_retry then 'pending' else 'review' end,
  provider_id=p_provider,accepted_at=case when p_provider is not null then clock_timestamp() else null end,
  available_at=clock_timestamp()+make_interval(secs=>least(3600,60*greatest(1,attempts))),lease_token=null,lease_until=null where id=p_job;
 if p_provider is not null then update bud_platform.owner_alerts set notified_at=clock_timestamp() where fingerprint=v_job.fingerprint and first_seen=v_job.cycle; end if;
 return jsonb_build_object('recorded',true,'accepted',p_provider is not null);
end;
$$;
do $$ declare f record; begin
 for f in select p.oid::regprocedure as signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace
  where (n.nspname='public' and p.proname in ('bud_owner_check','bud_owner_view','bud_owner_command','bud_bonus_redeem','bud_owner_recover_payment','bud_owner_sync_alerts','bud_owner_claim_notification','bud_owner_finish_notification','bud_owner_access_event'))
   or(n.nspname='bud_platform' and p.proname in ('require_owner','owner_directory','owner_user_count','guard_owner_restriction')) loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end $$;
commit;
